  $('#apiForm').onsubmit=event=>{event.preventDefault();const values={name:$('#apiName').value.trim(),url:$('#apiUrl').value.trim().replace(/\/$/,''),key:$('#apiKey').value.trim(),model:$('#apiModel').value.trim()};if(!values.name){$('#apiFeedback').textContent='请先填写配置名称。';$('#apiName').focus();return}let config=cfg.apiConfigs.find(item=>item.id===editingApiConfigId);if(config)Object.assign(config,values);else{config={id:`api-${Date.now()}`,...values};cfg.apiConfigs.push(config);editingApiConfigId=config.id}cfg.activeApiConfigId=config.id;cfg.apiUrl=values.url;cfg.apiKey=values.key;cfg.apiModel=values.model;save();refreshSettings();$('#apiFeedback').textContent='配置已保存并设为当前使用。'};
  $('#fetchModels').onclick=async()=>{const button=$('#fetchModels'),feedback=$('#apiFeedback'),base=$('#apiUrl').value.trim().replace(/\/+$/,'');if(!base){feedback.textContent='请先填写 API 地址。';return}button.disabled=true;button.textContent='正在拉取…';feedback.textContent='正在连接模型列表…';try{const endpoint=base.endsWith('/models')?base:`${base}/models`,key=$('#apiKey').value.trim();const response=await fetch(endpoint,{headers:key?{Authorization:`Bearer ${key}`}:{}});if(!response.ok)throw Error(`请求失败（${response.status}）`);const result=await response.json(),items=Array.isArray(result)?result:(result.data||result.models||[]),models=items.map(item=>typeof item==='string'?item:(item.id||item.name)).filter(Boolean);if(!models.length)throw Error('没有找到可用模型。');$('#apiModelOptions').innerHTML=models.map(model=>`<option value="${esc(model)}"></option>`).join('');feedback.textContent=`已拉取 ${models.length} 个模型，点击模型名称可选择。`}catch(error){feedback.textContent=`拉取失败：${error.message||'请检查地址、Key 或跨域设置。'}`}finally{button.disabled=false;button.textContent='拉取模型'}};
