function exportData(){const backup={format:'iris-backup',version:1,createdAt:new Date().toISOString(),data:state};const url=URL.createObjectURL(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`iris-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#storageFeedback').textContent='备份文件已导出。'}
async function importData(file){if(!file)return;const feedback=$('#storageFeedback');try{const parsed=JSON.parse(await file.text());const incoming=parsed?.data||parsed;if(!incoming||!Array.isArray(incoming.users)||!Array.isArray(incoming.characters)||!incoming.messages||typeof incoming.messages!=='object')throw Error('文件格式不正确。');if(!window.confirm('导入会替换当前浏览器中的用户、角色和聊天数据，继续吗？'))return;Object.assign(state,incoming);state.users=state.users.map(u=>typeof u==='string'?{name:u,nickname:'',birthday:'',details:'',avatar:''}:{name:'',nickname:'',birthday:'',details:'',avatar:'',...u});chars.splice(0,chars.length,...state.characters);state.char=chars.length?Math.max(0,Math.min(state.char,chars.length-1)):-1;state.user=state.users.length?Math.max(0,Math.min(state.user,state.users.length-1)):-1;state.settings={apiUrl:'',apiKey:'',apiModel:'',keepAlive:false,...(incoming.settings||{})};save();render();refreshSettings();feedback.textContent='数据已导入。'}catch(error){feedback.textContent=error.message||'导入失败。'}finally{$('#importDataFile').value=''}}
